<?php require_once '../includes/admin_header.php';$counts=[];foreach(['courses','academies','course_categories','freelancers','inquiries'] as $table)$counts[$table]=(int)db()->query("SELECT COUNT(*) FROM `$table`")->fetchColumn();$recent=db()->query("SELECT * FROM inquiries ORDER BY created_at DESC LIMIT 5")->fetchAll();$f=flash(); ?><div class="stat-grid"><div class="stat"><small>Courses</small><strong><?=$counts['courses']?></strong></div><div class="stat"><small>Academies</small><strong><?=$counts['academies']?></strong></div><div class="stat"><small>Freelancers</small><strong><?=$counts['freelancers']?></strong></div><div class="stat"><small>Course categories</small><strong><?=$counts['course_categories']?></strong></div><div class="stat"><small>Inquiries</small><strong><?=$counts['inquiries']?></strong></div></div><?php if($f):?><div class="notice"><?=$f['message']?></div><?php endif;?><div class="admin-head"><h2>Recent inquiries</h2><a class="btn btn-primary" href="manage.php?type=courses">Manage content +</a></div><div class="table-wrap"><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Type</th><th>Date</th><th></th></tr></thead><tbody><?php foreach($recent as $row):?><tr><td><b><?=e($row['name'])?></b></td><td><?=e($row['email'])?></td><td><span class="pill"><?=e($row['inquiry_type'])?></span></td><td><?=date('M j, Y',strtotime($row['created_at']))?></td><td><a class="action" href="manage.php?type=inquiries">View</a></td></tr><?php endforeach;?></tbody></table></div><?php require '../includes/admin_footer.php'; ?>